#!/usr/bin/env python3
import csv
import re
from collections import defaultdict
from datetime import date, timedelta
from pathlib import Path

LOG_DIR = Path("/app/logs")
OUTPUT = Path("/app/summary.csv")
REFERENCE_DATE = date(2025, 8, 12)
SEVERITIES = ("ERROR", "WARNING", "INFO")
PERIODS = ("today", "last_7_days", "last_30_days", "month_to_date", "total")

FILENAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")
LINE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}\s+\[(ERROR|WARNING|INFO)\]")


def in_period(log_date: date, period: str) -> bool:
    if period == "today":
        return log_date == REFERENCE_DATE
    if period == "last_7_days":
        return REFERENCE_DATE - timedelta(days=6) <= log_date <= REFERENCE_DATE
    if period == "last_30_days":
        return REFERENCE_DATE - timedelta(days=29) <= log_date <= REFERENCE_DATE
    if period == "month_to_date":
        return (
            log_date.year == REFERENCE_DATE.year
            and log_date.month == REFERENCE_DATE.month
            and log_date <= REFERENCE_DATE
        )
    if period == "total":
        return True
    raise ValueError(f"Unknown period: {period}")


def main() -> None:
    daily_counts = defaultdict(lambda: {severity: 0 for severity in SEVERITIES})

    for path in sorted(LOG_DIR.glob("*.log")):
        match = FILENAME_RE.match(path.name)
        if not match:
            continue
        log_date = date.fromisoformat(match.group(1))
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                line_match = LINE_RE.match(line)
                if line_match:
                    daily_counts[log_date][line_match.group(1)] += 1

    totals = {
        period: {severity: 0 for severity in SEVERITIES}
        for period in PERIODS
    }

    for log_date, counts in daily_counts.items():
        for period in PERIODS:
            if in_period(log_date, period):
                for severity in SEVERITIES:
                    totals[period][severity] += counts[severity]

    with OUTPUT.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(["period", "severity", "count"])
        for period in PERIODS:
            for severity in SEVERITIES:
                writer.writerow([period, severity, totals[period][severity]])


if __name__ == "__main__":
    main()
