import csv
from collections import defaultdict
from datetime import date, timedelta
from pathlib import Path

ref = date(2025, 8, 12)
severities = ['ERROR', 'WARNING', 'INFO']
periods = ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']
tokens = {'[' + s + ']': s for s in severities}
counts = defaultdict(lambda: {s: 0 for s in severities})

for path in sorted(Path('/app/logs').glob('*.log')):
    name = path.name
    if len(name) < 15 or name[10] != '_' or not name.endswith('.log'):
        continue
    try:
        d = date.fromisoformat(name[:10])
    except ValueError:
        continue
    with path.open(encoding='utf-8', errors='replace') as fh:
        for line in fh:
            parts = line.split(maxsplit=3)
            if len(parts) >= 3 and parts[2] in tokens:
                counts[d][tokens[parts[2]]] += 1

def included(d, period):
    if period == 'today':
        return d == ref
    if period == 'last_7_days':
        return ref - timedelta(days=6) <= d <= ref
    if period == 'last_30_days':
        return ref - timedelta(days=29) <= d <= ref
    if period == 'month_to_date':
        return d.year == ref.year and d.month == ref.month and d <= ref
    return True

expected = [['period', 'severity', 'count']]
for period in periods:
    for severity in severities:
        total = sum(c[severity] for d, c in counts.items() if included(d, period))
        expected.append([period, severity, str(total)])

with Path('/app/summary.csv').open(newline='', encoding='utf-8') as fh:
    actual = list(csv.reader(fh))

print('Independent expected CSV:')
for row in expected:
    print(','.join(row))

if actual != expected:
    print('MISMATCH: actual CSV was:')
    for row in actual:
        print(','.join(row))
    raise SystemExit(1)

print('VERIFIED: summary.csv matches independent recount')
